package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import static org.junit.jupiter.api.Assertions.*;
import com.microsoft.playwright.*;import com.microsoft.playwright.options.AriaRole;import java.nio.file.Path;import java.util.*;
final class SupportConversationsBrowserAcceptance {
    static void run(BrowserTest h)throws Exception{
        String article,user="SupportBrowser"+id().substring(0,8);try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Service.createAccount(db,map("name",user,"password",WorkflowSupport.PASSWORD,"role","requester"));article=KnowledgeSearchAcceptance.article(db,actor,"Browser support evidence","Use the approved request form.");db.connection.commit();}
        try(var provider=new RecordQuestionsAcceptance.Provider(h.store,h.store.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
            provider.settings.put("AI_SUPPORT_ENABLED","true");provider.answer.set("Which approved form do you need? <script>untrusted</script>");var page=context.newPage();FulfilmentBrowserAcceptance.login(h,page,user);page.navigate(h.base()+"/knowledge/"+article);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Start a support conversation")).press("Enter");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create private conversation")).press("Enter");String url=page.url();
            page.getByLabel("Your question").fill("I need help with a form");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Preview external request")).press("Enter");assertEquals(0,provider.calls.get());assertThat(page.locator("main")).containsText("I need help with a form");page.getByLabel("Send this question, history and article to the configured provider").check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Ask with reviewed context")).press("Enter");assertThat(page.locator("main")).containsText(provider.answer.get());assertThat(page.locator("main script")).hasCount(0);page.reload();assertThat(page.locator("main")).containsText(provider.answer.get());assertEquals(1,provider.calls.get());
            page.getByLabel("Your question").fill("The equipment request form");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Preview external request")).press("Enter");assertThat(page.locator("pre")).containsText("I need help with a form");page.getByLabel("Send this question, history and article to the configured provider").check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Ask with reviewed context")).press("Enter");assertEquals(2,provider.calls.get());new Store(h.store.environment);page.navigate(url);assertThat(page.locator("main")).containsText("The equipment request form");var export=context.request().get(url+"/export");assertEquals(200,export.status());assertTrue(export.text().contains("equipment request"));
            page.getByLabel("Request summary").fill("Help complete equipment request");page.getByLabel("Request details").fill("Please help me complete the approved form");page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Review human follow-up")).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Confirm the service request"))).isVisible();assertThat(page.locator("pre")).containsText("The equipment request form");
            for(String theme:new String[]{"light","dark"}){if(theme.equals("dark")){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).click();page.setViewportSize(390,844);}ReleaseBrowserAcceptance.checkAccessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/support-conversation-"+theme+".png")).setFullPage(true));}
            provider.settings.put("AI_ENABLED","false");page.getByLabel("Submit this request and share the reviewed context with the service team").check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Submit human follow-up")).press("Enter");assertThat(page.locator("main")).containsText("Human follow-up requested");page.reload();assertEquals(2,provider.calls.get());page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Open your service request")).press("Enter");assertThat(page.locator("main")).containsText("Help complete equipment request");assertThat(page.locator("main")).containsText("The equipment request form");page.navigate(h.base()+"/support");page.getByLabel("Delete this conversation permanently").check();page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Delete conversation")).press("Enter");assertThat(page.locator("main")).containsText("No retained conversations");assertEquals(404,context.request().get(url).status());
        }
    }
}
